"""Middle grades: basic sentence roles and discourse connections."""
def author(E,C,O,A,D):
 E('plan-G3-language-06','S2','기록 카드의 세 자리',
 '관찰 기록: 지안이가 나뭇잎을 펼쳤다.\n세현이는 손전등을 켰다.\n유리는 돋보기를 닦았다.\n기록 카드에는 누가 / 무엇을 / 어떻게 했나의 세 칸이 있다.',
 '이 자료의 행동 문장을 세 역할로 나누고 다시 구성한다. 모든 한국어 문장이 세 칸을 의무적으로 채운다고 가르치지 않는다.',[
 A('explanation','세현이의 일을 세 칸으로 나눈 뒤 다시 한 문장으로 써 보세요.','누가:세현이 / 무엇을:손전등 / 어떻게 했나:켰다. 세현이가 손전등을 켰다.','세현이는 손전등을 켰다.',[D('역할 구별','세현이·손전등·켰다를 역할에 맞게 나눈다.','세 칸 중 하나가 빠지거나 뒤바뀐다.','손전등이 세현이를 켰다고 나눈다.'),D('문장 구성','행동 주체와 대상을 보존한 자연스러운 문장을 만든다.','역할은 알지만 낱말만 나열한다.','손전등을 닦았다고 원래 행동을 바꾼다.')]),
 C('유리가 한 일을 나타내는 부분은 무엇인가요?','닦았다','유리의 문장에서 어떻게 했는지 나타내는 말이다.',[('유리는','행동한 대상을 나타낸다.'),('돋보기를','닦은 물건을 나타낸다.'),('손전등을','다른 사람이 켠 물건이다.')],'유리는 돋보기를 닦았다.'),
 O('matching','지안이의 문장을 누가 / 무엇을 / 어떻게 했나에 맞게 나누세요.','지안이 / 나뭇잎 / 펼쳤다','지안이가 나뭇잎을 펼쳤다.','한 칸을 빠뜨림','행동한 대상과 물건을 바꿈'),
 O('explanation','유리의 문장에서 돋보기를이 빠졌을 때, 처음 읽는 사람은 어떤 정보를 모를 수 있나요?','무엇을 닦았는지 모를 수 있다. 앞뒤 상황이 있으면 알 수도 있다.','유리는 돋보기를','무언가 빠졌다고만 함','유리가 누구인지 절대로 알 수 없다고 함')])
 E('plan-G3-language-06','S3','순서가 바뀌어도 남는 역할',
 '기록 가: 하준이가 작은 깃발을 들었다.\n기록 나: 작은 깃발을 하준이가 들었다.\n기록 다: 작은 깃발이 하준이를 가렸다.\n가와 나는 같은 장면을 서로 다른 말 차례로 적었다. 다는 깃발이 얼굴 앞을 가린 다른 장면이다.',
 '단순히 문장의 첫 낱말을 주체로 고르지 않는다. 초3에서는 누가 무엇을 하는지의 기본 관계로 다루며 주제 조사 은·는을 주어 표지로 일반화하지 않는다.',[
 A('explanation','가와 나에서 깃발을 든 사람은 각각 누구인가요? 다의 관계와도 비교하세요.','가와 나 모두 하준이가 깃발을 들었다. 다는 깃발이 하준이를 가린 장면으로 행동 관계가 다르다.',['기록 가: 하준이가','기록 나: 작은 깃발을','기록 다: 작은 깃발이'],[D('같은 관계 연결','가와 나의 하준이·깃발·들기 관계가 같음을 설명한다.','한 문장만 바르게 설명한다.','나는 깃발이 하준이를 들었다고 한다.'),D('달라진 관계','다는 깃발이 가리고 하준이가 가려지는 관계임을 구별한다.','다는 다르다고만 한다.','말 차례만 다르므로 다도 같은 장면이라고 한다.')]),
 C('기록 나를 읽은 설명으로 맞는 것은 무엇인가요?','하준이가 작은 깃발을 든 장면이다.','깃발을은 든 물건이고 하준이가가 든 사람이다. 첫 낱말만으로 역할을 정하지 않는다.',[('작은 깃발이 하준이를 가린 장면이다.','이것은 기록 다의 관계이다.'),('하준이가 작은 깃발을 가린 장면이다.','기록 나의 들기를 가리기로 바꾸었다.'),('작은 깃발이 하준이를 든 장면이다.','앞에 놓인 말을 주체로 읽어 든 사람과 물건을 뒤집었다.')],'작은 깃발을 하준이가 들었다.'),
 O('explanation','기록 다를 하준이부터 시작해 뜻이 같게 써 보세요.','하준이는 작은 깃발에 가려졌다. 같은 뜻을 보존한 다른 문장도 수용한다.','작은 깃발이 하준이를 가렸다.','하준이를 앞에 두지만 가려지는 관계가 흐림','하준이가 깃발을 가렸다고 바꿈'),
 O('evidence_selection','가와 나가 같은 장면이라고 밝힌 부분을 찾으세요.','가와 나는 같은 장면을 서로 다른 말 차례로 적었다.','같은 장면을 서로 다른 말 차례로','같은 장면만 짚음','다는 다른 장면이라는 말만 고름')])
 E('plan-G3-language-06','S4','대화에서 생략된 물건',
 '하늘이는 새 줄넘기를 들고 체육관으로 갔다.\n준호: “줄넘기는 어디에 둘까?”\n하늘: “바구니에 넣어 줘.”\n준호는 줄넘기를 바구니 안에 넣었다. 곁에 있던 공은 바닥에 그대로 두었다.',
 '넣어 줘의 대상은 앞의 질문과 뒤의 행동으로 복원한다. 물건을 생략한 문장이 곧 잘못이라는 규칙을 만들지 않는다.',[
 A('explanation','하늘의 말에 생략된 물건을 넣어, 이 대화를 처음 보는 사람도 알 수 있게 써 보세요. 그렇게 읽은 근거도 설명하세요.','줄넘기를 바구니에 넣어 줘. 앞에서 준호가 줄넘기를 어디에 둘지 물었고 뒤에서도 그것을 넣었다.',['줄넘기는 어디에 둘까','준호는 줄넘기를 바구니 안에'],[D('문맥에 맞는 보충','줄넘기를 넣으라는 뜻을 보존해 문장을 쓴다.','줄넘기를 고르지만 바구니와의 관계가 빠진다.','공을 넣으라는 말로 바꾼다.'),D('앞뒤 근거','앞의 질문 또는 뒤의 실제 행동을 생략된 대상과 연결한다.','그럴 것 같다고만 한다.','근처에 있는 물건은 모두 넣었다고 한다.')]),
 C('이 장면에서 바구니에 넣지 않은 물건으로 명시된 것은 무엇인가요?','공','공은 바닥에 그대로 두었다고 구별해 적혀 있다.',[('줄넘기','바구니에 넣었다.'),('바구니','물건을 넣는 곳이며 바닥에 둔 물건이라는 기록이 아니다.'),('새 운동화','이 장면에서 언급하지 않았다.')],'곁에 있던 공은 바닥에 그대로'),
 O('explanation','대화에서 바구니에 넣어 줘만 말해도 통할 수 있는 이유는 무엇인가요?','바로 앞에서 줄넘기 이야기를 했으므로 상대가 넣을 대상을 알 수 있기 때문이다.','준호: “줄넘기는 어디에','대화 중이기 때문이라고만 함','한국어는 어떤 물건이든 항상 생략해도 통한다고 함'),
 O('explanation','이 말만 별도의 쪽지에 적고 물건이 여러 개 놓여 있다면 어떤 말을 더 확인하면 좋을까요?','어떤 물건을 넣어야 하는지 확인하면 좋다. 문맥 없이 줄넘기라고 확정하지 않는다.','하늘: “바구니에 넣어 줘.”','모르겠다고만 함','물건 여러 개를 모두 넣어야 한다고 단정함')])
 E('plan-G3-language-06','S5','인물과 물건이 바뀐 설명',
 '실제 장면: 수민이가 커튼을 닫았다. 이어서 태린이가 창가 의자를 옮겼다.\n초고: 커튼이 수민이를 닫았다. 태린이는 옮겼다.\n이 글은 장면을 보지 못한 친구에게 누가 무엇을 했는지 알려 주려는 설명이다.',
 '첫 문장의 뒤바뀐 관계와 두 번째 문장의 독자에게 필요한 정보 누락을 따로 본다. 태린이는 옮겼다는 문장 자체를 모든 문맥에서 비문이라고 판정하지 않는다.',[
 A('explanation','초고 두 문장을 목적에 맞게 고치고, 각각 무엇을 고쳤는지 설명하세요.','수민이가 커튼을 닫았다. 태린이가 창가 의자를 옮겼다. 첫 문장은 닫은 사람과 대상을 바로잡고 둘째 문장은 옮긴 물건을 밝혔다.',['수민이가 커튼을 닫았다.','태린이가 창가 의자를 옮겼다.'],[D('두 문장 수정','닫은 사람·대상을 바로잡고 옮긴 물건을 밝힌다.','두 문제 중 하나만 고친다.','커튼이 사람을 닫는 관계를 유지한다.'),D('독자와 뜻','장면을 못 본 독자에게 행동 관계와 물건 정보가 필요함을 설명한다.','어색해서라고만 한다.','이름은 모든 문장에 반드시 반복해야 한다고만 한다.')]),
 C('둘째 문장에 의자를 넣는 가장 알맞은 이유는 무엇인가요?','처음 보는 독자에게 옮긴 물건을 알려 주려고','설명의 목적에 따라 빠진 물건 정보를 보충한다.',[('옮겼다는 말은 언제나 틀린 말이므로','문맥에 따라 대상을 생략할 수 있다.'),('문장을 길게 해야 언제나 좋은 글이므로','필요한 정보가 기준이며 길이 자체가 기준은 아니다.'),('태린이가 커튼도 닫았음을 알리려고','실제 장면의 행동을 바꾼다.')],'장면을 보지 못한 친구에게'),
 O('matching','첫 문장의 문제 / 둘째 문장의 문제를 각각 써 보세요.','첫 문장:행동 주체와 대상이 바뀜. 둘째 문장:이 독자에게 필요한 옮긴 물건이 빠짐.',['커튼이 수민이를 닫았다.','태린이는 옮겼다.'],'한 문제만 구별함','두 문장 모두 물건 이름이 없다고 함'),
 O('explanation','바로 앞에서 의자를 옮길지 대화한 상황이라면 태린이는 옮겼다가 통할 수도 있나요?','그럴 수 있다. 앞뒤에서 의자를 가리킨다는 것을 알 수 있기 때문이다. 이 설명문은 그런 대화가 없는 독자를 위한 것이다.','누가 무엇을 했는지 알려 주려는','가능하다고만 하고 상황 차이는 설명하지 못함','대상이 생략되면 언제나 틀렸다고 함'),
 O('evidence_selection','글을 고칠 때 독자를 고려해야 하는 단서를 찾으세요.','장면을 보지 못한 친구에게 누가 무엇을 했는지 알려 주려는 설명이다.','장면을 보지 못한 친구에게','친구라는 말만 짚음','실제 장면의 이름만 고름')])

 E('plan-G4-language-10','S2','이어 주는 말의 약속',
 '가: 연습실 문이 잠겼다. 그래서 우리는 운동장에서 연습했다. 문을 열 수 없어 연습 장소를 바꾼 것이다.\n나: 운동장은 넓었다. 하지만 바닥에 물이 고여 있었다.\n다: 연습 전에 공을 챙겼다. 그리고 물병도 챙겼다.',
 '가의 원인·결과를 명시적으로 보완해 단순한 앞뒤 순서를 원인으로 단정하지 않게 한다. 접속어가 관계를 나타내지만 사실의 진위를 보장하지는 않는다.',[
 A('explanation','가·나·다의 이어 주는 말이 각각 어떤 관계를 나타내는지 짧게 설명하세요.','가는 잠긴 문 때문에 장소를 바꾼 까닭과 결과, 나는 넓다는 장점에 물이 고였다는 다른 면, 다는 챙긴 물건을 더하는 관계이다.',['그래서 우리는 운동장에서','하지만 바닥에 물이','그리고 물병도'],[D('세 관계 구별','원인·결과, 대조, 덧붙임을 각각 내용에 맞게 구별한다.','세 관계 중 한두 개만 설명한다.','모두 시간 순서라고 한다.'),D('내용 연결','접속어 이름만 나열하지 않고 양쪽 내용을 연결한다.','관계 이름만 적는다.','잠긴 문 때문에 물병을 챙겼다고 엉뚱하게 잇는다.')]),
 C('다에서 물병을 챙긴 일을 더해 주는 말은 무엇인가요?','그리고','공에 더해 물병을 챙긴 일을 나란히 잇는다.',[('그래서','가의 원인과 결과를 잇는 말이다.'),('하지만','나에서 다른 면을 드러내는 말이다.'),('때문에','가의 설명에 쓰인 까닭 표현으로 다의 접속어가 아니다.')],'그리고 물병도 챙겼다.'),
 O('matching','가는 왜 장소를 바꾸었나요? 나에는 운동장의 어떤 두 모습이 나오나요?','가:문을 열 수 없어서. 나:넓음과 물이 고여 있음.',['문을 열 수 없어','운동장은 넓었다.','하지만 바닥에 물이 고여 있었다.'],'한 자료의 관계만 설명함','가에서 바닥의 물 때문에 옮겼다고 함'),
 O('explanation','나를 그러나를 써서 같은 뜻으로 다시 써 보세요.','운동장은 넓었다. 그러나 바닥에 물이 고여 있었다.','나: 운동장은 넓었다.','그러나만 쓰고 양쪽 내용을 연결하지 않음','물이 고인 까닭이 넓기 때문이라고 바꿈')])
 E('plan-G4-language-10','S3','작품 설명의 세 연결',
 '종이 전시 안내 초고: 종이를 여러 번 접으면 두께가 늘어난다. (가) 받침 부분은 많이 접어 단단하게 만들었다.\n(나) 장식 부분은 얇게 펼쳐 놓았다. 받침과 달리 가벼워 보이게 하려는 선택이다.\n작품 옆에는 만드는 순서를 붙였다. (다) 사용한 종이의 크기도 적었다.\n글쓴이 메모: 가에는 앞의 성질을 제작 이유와 잇고, 나에는 받침과 장식의 다른 모습을 드러내고, 다에는 붙인 정보를 더하고 싶다.',
 '정답을 하나의 접속어만으로 제한하지 않는다. 메모의 의도와 양쪽 문장의 관계를 충족하면 대체 표현도 수용한다.',[
 A('explanation','가·나·다에 뜻을 잇는 말을 넣고 각각 왜 골랐는지 설명하세요.','예:가 그래서, 나 그러나, 다 그리고. 가는 두께 증가를 받침 제작과 잇고, 나는 두껍게 만든 받침과 얇게 편 장식을 대비하며, 다는 적은 정보를 덧붙인다.',['종이를 여러 번 접으면','받침과 달리 가벼워','사용한 종이의 크기도'],[D('관계에 맞는 연결','세 자리에 이유·대조·덧붙임을 보존하는 표현을 넣는다.','한두 자리만 의도에 맞게 잇는다.','가에 대조만 강제하는 등 메모와 반대로 잇는다.'),D('선택 이유','각 표현을 앞뒤 내용과 글쓴이 의도에 연결한다.','표현만 나열한다.','어떤 글에도 같은 말만 넣어야 한다고 한다.')]),
 C('다에 그리고를 넣을 때 드러나는 관계는 무엇인가요?','전시에 붙인 정보를 더하는 관계','순서 정보에 종이 크기 정보가 더해진다.',[('종이 크기 때문에 순서가 바뀐 관계','그런 원인은 제시되지 않았다.'),('순서 정보와 크기 정보가 충돌하는 관계','둘이 모순된다는 내용이 없다.'),('장식을 받침으로 바꾼 시간 순서','두 정보의 덧붙임과 다르다.')],'만드는 순서를 붙였다.'),
 O('explanation','가에 그래서 대신 쓸 수 있는 표현을 하나 쓰고 같은 관계인지 설명하세요.','이 때문에 등. 두께가 늘어나는 성질을 이용해 받침을 많이 접었다는 관계를 보존하면 수용한다.','받침 부분은 많이 접어','대체 표현만 쓰고 관계 설명이 없음','하지만만 쓰며 이유가 같다고 함'),
 O('evidence_selection','장식과 받침을 다르게 만든 의도를 찾으세요.','받침과 달리 가벼워 보이게 하려는 선택이다.','받침과 달리 가벼워 보이게 하려는','가볍게라는 말만 짚음','종이 크기만 고름')])
 E('plan-G4-language-10','S4','그래서에 숨어 들어간 판단',
 '기록 가: 복도 조명을 바꾸었다. 그다음 일주일 동안 길을 묻는 학생이 줄었다. 같은 날 안내 표지도 새로 붙였다.\n학생의 설명: 조명을 바꾸었다. 그래서 길을 묻는 학생이 줄었다.\n이 기록에는 어느 변화가 문의 감소에 영향을 주었는지 따로 살핀 결과가 없다.',
 '그다음과 그래서의 차이를 읽고, 접속어 하나가 넣은 인과 판단을 설명한다. 조명이 효과가 없었다는 반대 단정도 피한다.',[
 A('explanation','그다음을 그래서로 바꾸면 어떤 판단이 더해지나요? 기록만으로 그 판단을 확정할 수 있는지도 설명하세요.','시간의 앞뒤에 더해 조명 변화가 문의 감소의 까닭이라는 판단이 들어간다. 표지도 함께 바꾸었고 따로 살핀 결과가 없어 조명만의 영향은 확정할 수 없다.',['그다음 일주일 동안','같은 날 안내 표지도','따로 살핀 결과가 없다.'],[D('연결 의미 차이','시간 순서와 원인·결과 판단의 차이를 설명한다.','그래서가 이유를 나타낸다고만 한다.','그다음도 언제나 원인이라고 한다.'),D('판단 범위','동시 표지 변경 또는 검증 부재를 들어 단정을 보류한다.','근거 없이 확신할 수 없다고만 한다.','조명은 절대로 영향이 없었다고 반대로 단정한다.')]),
 C('기록에 있는 시간 순서만 보존하는 표현은 무엇인가요?','조명을 바꾼 뒤 일주일 동안 문의가 줄었다.','뒤라는 표현은 순서를 전하며 조명만의 원인을 확정하지 않는다.',[('조명만 바꾼 덕분에 문의가 줄었다.','다른 변화와 원인 불확실성을 지운다.'),('안내 표지가 문의를 반드시 늘렸다.','실제 변화와 반대인 확정 주장이다.'),('문의가 줄었기 때문에 조명을 바꾸었다.','앞뒤를 뒤집고 원인도 새로 넣는다.')],'복도 조명을 바꾸었다.'),
 O('explanation','새 표지가 영향을 주었을 가능성을 덧붙여 설명을 고쳐 보세요.','조명과 표지를 함께 바꾼 뒤 문의가 줄었다. 어느 변화가 얼마나 영향을 주었는지는 더 살펴야 한다.','같은 날 안내 표지도 새로 붙였다.','표지도 바꾸었다는 사실만 덧붙임','표지만이 유일한 까닭이라고 확정함'),
 O('evidence_selection','원인을 따로 확인하지 않았음을 보여 주는 부분을 찾으세요.','어느 변화가 문의 감소에 영향을 주었는지 따로 살핀 결과가 없다.','어느 변화가 문의 감소에','문의가 줄었다는 결과만 짚음','조명이 바뀌었다는 사실만 고름')])
 E('plan-G4-language-10','S5','이유를 잇는 말은 맞을까',
 '확인 기록: 야외 낭독회 시작 직전에 비가 왔다. 진행자는 책이 젖지 않도록 실내로 자리를 옮겼다고 말했다.\n초고 가: 비가 왔다. 하지만 책이 젖지 않도록 실내로 옮겼다.\n초고 나: 실내로 옮겼다. 그래서 비가 왔다.\n글의 목적: 날씨 때문에 장소를 바꾼 이유를 분명히 전한다.',
 '하지만이 언제나 비문이라고 하지 않는다. 주어진 글의 인과 전달 목적에 더 알맞은 연결을 고르고, 원인·결과를 뒤집은 초고와 구별한다.',[
 A('explanation','글의 목적에 맞게 두 초고를 하나의 설명으로 고치고 수정 이유를 쓰세요.','비가 왔다. 그래서 책이 젖지 않도록 실내로 옮겼다. 또는 비가 와서 실내로 옮겼다. 대조보다 까닭과 결과를 분명히 잇고, 비와 장소 변경의 관계를 뒤집지 않도록 했다.',['책이 젖지 않도록 실내로 자리를','날씨 때문에 장소를 바꾼'],[D('인과 보존 수정','비가 원인이고 실내 이동이 대응임을 보존해 쓴다.','맞는 접속어만 쓰고 문장을 완성하지 못한다.','실내 이동이 비를 내리게 했다고 쓴다.'),D('목적에 따른 이유','가의 대조와 나의 뒤집힌 인과를 구별해 수정 이유를 밝힌다.','어색해서라고만 한다.','하지만은 어느 문장에서도 쓸 수 없다고 한다.')]),
 C('초고 나에서 가장 먼저 바로잡아야 할 것은 무엇인가요?','까닭과 결과가 뒤바뀐 관계','기록은 비 때문에 장소를 옮겼다고 밝힌다.',[('실내로 옮긴 사실을 삭제하는 일','확인된 사실을 지우게 된다.'),('비를 눈으로 바꾸는 일','기록에 없는 날씨를 만든다.'),('하지만을 무조건 덧붙이는 일','뒤집힌 인과가 그대로 남는다.')],'진행자는 책이 젖지 않도록'),
 O('explanation','가의 하지만을 그래서로 고치면 이 글의 목적에 어떤 도움이 되나요?','다른 면을 대비하기보다 비 때문에 실내로 옮긴 까닭과 결과가 분명해진다.','초고 가: 비가 왔다.','잘 이어진다고만 함','비가 멎었다는 새로운 사실이 생긴다고 함'),
 O('explanation','그래서 없이도 같은 이유를 분명히 전하는 문장을 써 보세요.','비가 와서 책이 젖지 않도록 낭독회 장소를 실내로 옮겼다.','야외 낭독회 시작 직전에 비가 왔다.','두 사실을 쓰지만 관계를 드러내지 못함','비가 오기 전에 행사가 끝났다고 바꿈'),
 O('evidence_selection','장소를 옮긴 이유가 단순한 추측이 아님을 보여 주는 기록을 찾으세요.','진행자는 책이 젖지 않도록 실내로 자리를 옮겼다고 말했다.','진행자는 책이 젖지 않도록','비가 왔다는 말만 고름','글의 목적만 쓰고 확인된 설명을 찾지 못함')])
